#include <bits/stdc++.h>
#define sec second
#define fst first
#define fast_input_output ios::sync_with_stdio(false); cin.tie(nullptr); cout.tie(nullptr)
#define output(n) return cout << n, 0
#define set_precision(n) cout << fixed << setprecision(n)
#define add_back push_back
#define long long long
#define long_double long double
#pragma GCC optimize("Ofast,no-stack-protector,unroll-loops")
using namespace std;

const int MAX_SIZE = 1e6 + 100, INF_VAL = 1e9 + 7, MOD_VAL = 1e9 + 7, P_CONST = 6151, T_CONST = 2000, SQ_CONST = 280, LOG_SIZE = 64, LOG2_SIZE = 34;
typedef pair<int, int> pair_int;

int total_nodes, base_d;
vector<int> digits;

struct node {
    int matrix[LOG2_SIZE][LOG2_SIZE], temp[LOG2_SIZE][LOG2_SIZE];
    bool visited[LOG2_SIZE], toggled[LOG2_SIZE];

    void combine(node &other) {
        for (int i = 0; i <= base_d; i++) {
            for (int j = 0; j <= base_d; j++) {
                matrix[i][j] = 0;
                for (int k = 0; k <= base_d; k++)
                    matrix[i][j] = (matrix[i][j] + matrix[k][j] * other.matrix[i][k]) % MOD_VAL;
            }
        }
        for (int i = 0; i < base_d; i++) {
            if (visited[i] && !other.visited[i]) {
                for (int j = 0; j <= base_d; j++)
                    matrix[i][j] = matrix[i][j];
            }
            if (!visited[i] && other.visited[i]) {
                for (int j = 0; j <= base_d; j++)
                    matrix[j][i] = other.matrix[j][i];
            }
            visited[i] |= other.visited[i];
        }
        for (int i = 0; i <= base_d; i++)
            for (int j = 0; j <= base_d; j++)
                matrix[i][j] = matrix[i][j];
    }

    void reset() {
        for (int i = 0; i <= base_d; i++)
            for (int j = 0; j <= base_d; j++)
                matrix[i][j] = temp[i][j] = 0;
    }

    void shift(int shift_value) {
        for (int i = 0; i <= base_d; i++)
            for (int j = 0; j <= base_d; j++)
                temp[i][j] = 0;
        for (int i = 0; i < base_d; i++) {
            for (int j = 0; j < base_d; j++)
                temp[(i + shift_value) % base_d][(j + shift_value) % base_d] = matrix[i][j];
            temp[(i + shift_value) % base_d][base_d] = matrix[i][base_d];
        }
        for (int i = 0; i < base_d; i++)
            temp[base_d][(i + shift_value) % base_d] = matrix[base_d][i];
        temp[base_d][base_d] = matrix[base_d][base_d];

        for (int i = 0; i <= base_d; i++)
            for (int j = 0; j <= base_d; j++)
                matrix[i][j] = temp[i][j];

        for (int i = 0; i < base_d; i++)
            toggled[i] = visited[(i + shift_value) % base_d];
        for (int i = 0; i < base_d; i++)
            visited[i] = toggled[i];
    }
} node_array[LOG_SIZE], helper[LOG_SIZE], temp_node;

node fetch_node(int x) {
    int h = x, power = 1, t_index = -1;
    while (h >= base_d) {
        h /= base_d;
        power *= base_d;
        t_index++;
    }
    x %= power;
    if (t_index == -1)
        return helper[h];
    node result_node = node_array[t_index];
    temp_node = node_array[t_index];
    for (int i = 1; i < h; i++) {
        temp_node.shift(1);
        result_node.combine(temp_node);
    }
    temp_node = node_array[t_index];
    temp_node = fetch_node(x);
    temp_node.shift(h);
    result_node.combine(temp_node);
    return result_node;
}

int main() {
    fast_input_output;
    cin >> total_nodes >> base_d;
    total_nodes--;
    int temp_n = total_nodes;
    while (total_nodes) {
        digits.push_back(total_nodes % base_d);
        total_nodes /= base_d;
    }
    node_array[0].matrix[base_d][base_d] = 2;
    node_array[0].matrix[base_d][0] = -1;
    node_array[0].matrix[0][base_d] = 1;
    node_array[0].visited[0] = true;
    node_array[0] = helper[0];
    for (int i = 1; i < base_d; i++) {
        node_array[i].matrix[base_d][base_d] = 2;
        node_array[i].matrix[base_d][i] = -1;
        node_array[i].matrix[i][base_d] = 1;
        node_array[i].visited[i] = true;
        helper[0].merge(node_array[i]);
        node_array[i] = helper[0];
    }
    for (int i = 1; i <= (int)digits.size(); i++) {
        node_array[i] = node_array[i - 1];
        temp_node = node_array[i - 1];
        for (int j = 1; j < base_d; j++) {
            temp_node.shift(1);
            helper[i].merge(temp_node);
        }
    }
    node final_ans = fetch_node(temp_n);
    cout << final_ans.matrix[base_d][base_d] << "\n";
    return 0;
}
